import { useMemo, useRef, useState } from "react";
import { SectionPage, Specimen } from "../kit.js";
import { defineActions, ActionMenu, useActionShortcuts } from "../../ui/actions/index.js";
import { Button } from "../../ui/button/index.js";
import { Input } from "../../ui/input/index.js";
import { Kbd } from "../../ui/kbd/index.js";
import {
  KeymapProvider,
  ShortcutHelpDialog,
  ShortcutPending,
  useCommandBinding,
  useShortcutCommands,
  type Keymap,
  type ShortcutCommand,
} from "../../ui/keymap/index.js";
import { Menu } from "../../ui/menu/index.js";
import { StatusBar } from "../../ui/status-bar/index.js";

interface Note {
  name: string;
}

const NOTE: readonly Note[] = [{ name: "Harbour survey" }];

function Commands({ onRun, onHelp }: { onRun: (label: string) => void; onHelp: () => void }) {
  const commands = useMemo<ShortcutCommand[]>(
    () => [
      { id: "help.open", label: "Show keyboard shortcuts", group: "Help", keys: "?", run: onHelp },
      {
        id: "file.save",
        label: "Save",
        group: "File",
        keys: "mod+s",
        textEntry: "inputs",
        run: () => onRun("Save"),
      },
      {
        id: "file.saveAll",
        label: "Save all",
        group: "File",
        keys: "mod+k mod+s",
        textEntry: "inputs",
        run: () => onRun("Save all"),
      },
      {
        id: "view.zen",
        label: "Hide panels",
        group: "View",
        keys: ["mod+k z", "f11"],
        run: () => onRun("Hide panels"),
      },
      {
        id: "view.next",
        label: "Next view",
        group: "View",
        keys: "g n",
        run: () => onRun("Next view"),
      },
      {
        id: "file.print",
        label: "Print",
        group: "File",
        disabledReason: "Nothing is open",
        keys: "mod+p",
        run: () => onRun("Print"),
      },
    ],
    [onHelp, onRun],
  );
  useShortcutCommands(commands);
  return null;
}

const noteActions = defineActions<Note>("note", [
  {
    id: "duplicate",
    label: "Duplicate",
    group: "manage",
    shortcut: "mod+k d",
    run: () => undefined,
  },
  {
    id: "archive",
    label: "Archive",
    group: "organise",
    shortcut: "mod+shift+a",
    run: () => undefined,
  },
]);

function ActionKeys() {
  useActionShortcuts(noteActions, NOTE, "Notes");
  return <ActionMenu set={noteActions} targets={NOTE} label="Harbour survey" />;
}

/** Tool keys that work only while the canvas has focus; the menu shows them read-only. */
function ScopedTools({ onRun }: { onRun: (label: string) => void }) {
  const canvas = useRef<HTMLDivElement>(null);
  const commands = useMemo<ShortcutCommand[]>(
    () => [
      {
        id: "tool.brush",
        label: "Brush",
        group: "Canvas",
        context: "canvas",
        keys: "b",
        scope: canvas,
        run: () => onRun("Brush"),
      },
      {
        id: "tool.erase",
        label: "Eraser",
        group: "Canvas",
        context: "canvas",
        keys: "e",
        scope: canvas,
        run: () => onRun("Eraser"),
      },
    ],
    [onRun],
  );
  useShortcutCommands(commands);
  const brush = useCommandBinding("tool.brush");
  const eraser = useCommandBinding("tool.erase");
  return (
    <div className="flex flex-wrap items-center gap-3">
      <div
        ref={canvas}
        tabIndex={0}
        role="application"
        aria-label="Canvas"
        className="grid h-16 w-56 max-w-full place-items-center rounded-md bg-fill-subtle"
        data-testid="keymap-canvas"
      >
        <span className="type-caption text-fg-muted">Focus here, then press B or E</span>
      </div>
      <Menu.Root>
        <Menu.Trigger render={<Button variant="secondary">Tools</Button>} />
        <Menu.Popup>
          <Menu.Item shortcut={brush.primary} onClick={() => onRun("Brush")}>
            Brush
          </Menu.Item>
          <Menu.Item shortcut={eraser.primary} onClick={() => onRun("Eraser")}>
            Eraser
          </Menu.Item>
        </Menu.Popup>
      </Menu.Root>
    </div>
  );
}

function KeymapDemo() {
  const [keymap, setKeymap] = useState<Keymap>({});
  const [help, setHelp] = useState(false);
  const [last, setLast] = useState("Nothing yet");
  const onHelp = useMemo(() => () => setHelp(true), []);
  return (
    <KeymapProvider keymap={keymap} onKeymapChange={setKeymap} pendingDisplay="none">
      <Commands onRun={setLast} onHelp={onHelp} />
      <div className="flex w-full flex-col gap-3" data-testid="keymap-demo">
        <div className="flex flex-wrap items-center gap-3">
          <Button onClick={() => setHelp(true)}>Keyboard shortcuts</Button>
          <ActionKeys />
          <Input aria-label="Note title" placeholder="Note title" className="w-56 max-w-full" />
        </div>
        <ScopedTools onRun={setLast} />
        <StatusBar aria-label="Keyboard status">
          <StatusBar.Start>
            <StatusBar.Item>Last command: {last}</StatusBar.Item>
          </StatusBar.Start>
          <StatusBar.End>
            <ShortcutPending />
          </StatusBar.End>
        </StatusBar>
        <div className="flex flex-wrap items-center gap-6" data-testid="kbd-chords">
          <Kbd keys="mod+k mod+s" />
          <Kbd keys="mod+k mod+s" size="sm" />
          <Kbd keys="g e" />
          <Kbd keys="mod+k z" variant="text" />
        </div>
        <pre className="type-caption text-fg-muted" data-testid="keymap-json">
          {JSON.stringify(keymap)}
        </pre>
      </div>
      <ShortcutHelpDialog
        open={help}
        onOpenChange={setHelp}
        rebind
        groupOrder={["File", "View", "Notes", "Help"]}
      />
    </KeymapProvider>
  );
}

export default function KeymapSection() {
  return (
    <SectionPage>
      <Specimen
        title="Dispatcher, rebinding and help"
        description="Try Ctrl K, then S (⌘K, then S on a Mac): the chord in progress shows in the status bar and times out after three seconds. Save runs from the title field because its binding asks to. Press ? for the help dialog, where each shortcut can be changed. Brush and Eraser are scoped: B and E work only while the canvas has focus, and the Tools menu shows them without taking them. The keymap below is the JSON a host would store."
        specimenKey="keymap:default:0"
      >
        <KeymapDemo />
      </Specimen>
    </SectionPage>
  );
}
